.sffc-cv-match-studio {
  --cv-match-bg: #eef2f8;
  --cv-match-surface: #ffffff;
  --cv-match-surface-strong: #ffffff;
  --cv-match-border: rgba(44, 42, 37, 0.08);
  --cv-match-border-strong: rgba(44, 42, 37, 0.14);
  --cv-match-ink: #1d1c17;
  --cv-match-muted: #736d63;
  --cv-match-accent: #15352f;
  --cv-match-accent-soft: #e9f1ed;
  --cv-match-dark: #101917;
  --cv-match-dark-muted: rgba(255, 255, 255, 0.68);
  --cv-match-pill: #f4f1eb;
  --cv-match-shadow: 0 28px 70px rgba(28, 27, 24, 0.08);
  background: linear-gradient(180deg, #eef3f9 0%, #e8eef5 100%);
  color: var(--cv-match-ink);
  font-family: Tahoma, Arial, sans-serif;
  width: 100vw;
  max-width: 100vw;
  margin-left: calc(50% - 50vw);
  margin-right: calc(50% - 50vw);
  position: relative;
  min-height: 100vh;
  margin-top: -10px;
  margin-bottom: -10px;
}

