.sffc-cv-match-job-posts,
.sffc-cv-match-job-posts * {
  box-sizing: border-box;
}

.sffc-cv-match-job-posts {
  display: block;
  position: relative;
  background: #ffffff;
  color: #141b24;
  font-family: Tahoma, Arial, sans-serif;
  width: 100vw;
  max-width: 100vw;
  min-height: 100vh;
  height: auto;
  max-height: none;
  margin: 0 calc(50% - 50vw);
  overflow: visible;
}

.sffc-cv-match-job-posts--signup-overlay {
  background: #f3f2ef;
}

.sffc-cv-match-studio__jobs-posts-shell {
  width: min(1320px, calc(100% - 48px));
  margin: 0 auto;
  padding: 0 0 88px;
  display: grid;
  gap: 44px;
}

.sffc-cv-match-job-posts--finance-community .sffc-cv-match-studio__jobs-posts-shell {
  padding-top: 20px;
}

.sffc-cv-match-studio__community-headerbar {
  position: sticky;
  top: 0;
  z-index: 80;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 18px;
  min-height: 84px;
  padding: 0 24px;
  border-top: 1px solid #dfe5eb;
  border-bottom: 1px solid #dfe5eb;
  background: rgba(255, 255, 255, 0.94);
