@supports (height: 100dvh) {
  .sffc-cv-match-studio,
  .sffc-cv-match-studio__shell,
  .sffc-cv-match-studio__sidebar,
  .sffc-cv-match-studio__main {
    min-height: 100dvh;
    height: 100dvh;
  }

  .sffc-cv-match-studio__job-view {
    min-height: auto;
  }
}

@media (max-width: 1100px) {
  .sffc-cv-match-studio {
    min-height: 100dvh;
    margin-top: 0;
    margin-bottom: 0;
    background: linear-gradient(180deg, #eaf1f8 0%, #e3ebf4 100%);
  }

  .sffc-cv-match-studio__shell {
    grid-template-columns: 1fr;
    min-height: 100dvh;
    height: 100dvh;
  }

  .sffc-cv-match-studio__sidebar {
    display: flex;
    position: fixed;
    top: 0;
    left: 0;
    bottom: 0;
    width: min(304px, calc(100vw - 28px));
    min-height: 100dvh;
    height: 100dvh;
    z-index: 90;
    transform: translateX(-108%);
    transition: transform 0.24s ease;
    box-shadow: 0 28px 48px rgba(3, 10, 16, 0.28);
    border-right: 1px solid rgba(255, 255, 255, 0.08);
  }

  .sffc-cv-match-studio.is-mobile-nav-open .sffc-cv-match-studio__sidebar {
    transform: translateX(0);
  }

  .sffc-cv-match-studio__main {
    min-height: 100dvh;
    height: 100dvh;
    padding: calc(env(safe-area-inset-top) + 14px) 14px
      calc(env(safe-area-inset-bottom) + 20px);
    overflow: auto;
    overscroll-behavior: contain;
  }

  .sffc-cv-match-studio__mobile-nav-toggle {
    position: relative;
    z-index: 1;
    flex: 0 0 auto;
    width: 42px;
    height: 42px;
    padding: 0;
    border: 0;
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.94);
    color: #173b5d;
    display: inline-flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 4px;
    box-shadow: 0 12px 24px rgba(15, 23, 42, 0.12);
    backdrop-filter: blur(14px);
  }

  .sffc-cv-match-studio__mobile-nav-toggle span {
    width: 16px;
    height: 2px;
    border-radius: 999px;
    background: currentColor;
    display: block;
  }

  .sffc-cv-match-studio__mobile-nav-backdrop {
    position: fixed;
    inset: 0;
    z-index: 80;
    background: rgba(15, 23, 42, 0.22);
    backdrop-filter: blur(6px);
  }

  .sffc-cv-match-studio__hero {
    margin-top: 28px;
  }

  .sffc-cv-match-studio__hero h1 {
    font-size: clamp(34px, 7vw, 52px);
    line-height: 0.98;
  }

  .sffc-cv-match-studio__hero-copy {
    font-size: 15px;
    line-height: 1.7;
  }

  .sffc-cv-match-studio__results-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .sffc-cv-match-studio__results-controls,
  .sffc-cv-match-studio__topbar,
  .sffc-cv-match-studio__prompt-bar {
    flex-direction: column;
    align-items: stretch;
  }

  .sffc-cv-match-studio__topbar-actions,
  .sffc-cv-match-studio__results-filters {
    width: 100%;
  }

  .sffc-cv-match-studio__results-filters {
    display: grid;
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .sffc-cv-match-studio__results-surface {
    gap: 14px;
  }

  .sffc-cv-match-studio__job-view {
    min-height: auto;
  }
}

@media (max-width: 900px) {
  .sffc-cv-match-studio__table-wrap {
    overflow: visible;
    padding: 0;
    background: transparent;
  }

  .sffc-cv-match-studio__table,
  .sffc-cv-match-studio__table tbody,
  .sffc-cv-match-studio__table tr,
  .sffc-cv-match-studio__table td {
    display: block;
    width: 100%;
  }

  .sffc-cv-match-studio__table {
    min-width: 0;
    border-spacing: 0;
  }

  .sffc-cv-match-studio__table thead {
    display: none;
  }

  .sffc-cv-match-studio__table tbody {
    display: grid;
    gap: 12px;
  }

  .sffc-cv-match-studio__result-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas:
      "role match"
      "recruiter recruiter"
      "contact roles"
      "materials materials"
      "action action";
    gap: 10px 12px;
    padding: 14px;
    border-radius: 22px;
    background: linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.88) 0%,
      rgba(244, 248, 255, 0.98) 100%
    );
    border: 1px solid rgba(23, 27, 36, 0.08);
    box-shadow: 0 16px 34px rgba(23, 41, 66, 0.08);
    overflow: hidden;
  }

  .sffc-cv-match-studio__table tbody tr.sffc-cv-match-studio__result-row td {
    padding: 0;
    background: transparent;
    border: 0;
    min-width: 0;
  }

  .sffc-cv-match-studio__mobile-cell-label {
    display: none;
  }

  .sffc-cv-match-studio__detail-row {
    display: none !important;
  }

  .sffc-cv-match-studio__table
    tbody
    tr.sffc-cv-match-studio__result-row
    td:nth-child(1) {
    grid-area: match;
    justify-self: end;
    align-self: start;
  }

  .sffc-cv-match-studio__table
