/* Editorial redesign: section-specific controls */

/* Main canvas */
.sffc-cv-match-studio__main {
  background: #faf8f5;
  color: #22324b;
  font-family: Tahoma, Arial, sans-serif;
}

.sffc-cv-match-studio__main--landing-view,
.sffc-cv-match-studio__main[data-cv-match-main-state="landing"] {
  background: radial-gradient(
      circle at top center,
      rgba(239, 235, 224, 0.52),
      transparent 36%
    ),
    #faf8f5;
}

.sffc-cv-match-studio__main--results-view,
.sffc-cv-match-studio__main[data-cv-match-main-state="results"] {
  background: linear-gradient(
    180deg,
    rgba(250, 248, 245, 0.96) 0%,
    rgba(247, 243, 235, 0.96) 100%
  );
}

/* Utility/top controls */
.sffc-cv-match-studio__main-utility {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-bottom: 18px;
}

.sffc-cv-match-studio__recommended-searchbar {
  flex: 1 1 auto;
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  max-width: 840px;
  margin: 0 auto;
  padding: 12px 14px 12px 16px;
  border: 1px solid rgba(44, 61, 92, 0.08);
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.72);
  box-shadow: 0 14px 30px rgba(17, 30, 46, 0.05);
  backdrop-filter: blur(14px);
}

.sffc-cv-match-studio__recommended-searchbar--inline {
  width: 100%;
  max-width: none;
  margin: 0;
  box-shadow: 0 12px 24px rgba(17, 30, 46, 0.04);
}

.sffc-cv-match-studio__recommended-searchbar-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #6f8096;
}

.sffc-cv-match-studio__recommended-searchbar-icon svg {
  width: 18px;
  height: 18px;
}

.sffc-cv-match-studio__recommended-searchbar-input {
  width: 100%;
  min-height: 42px;
  padding: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: #1d2f4c;
  font-family: Tahoma, Arial, sans-serif;
  font-size: 15px;
  line-height: 1.2;
}

.sffc-cv-match-studio__recommended-searchbar-input::placeholder {
  color: #98a4b5;
}

.sffc-cv-match-studio__recommended-searchbar-submit {
  appearance: none;
  border-radius: 12px;
  font-family: Tahoma, Arial, sans-serif;
  font-size: 13px;
  font-weight: 400;
  cursor: pointer;
  transition: transform 0.18s ease, box-shadow 0.18s ease,
    border-color 0.18s ease;
  min-height: 40px;
  padding: 0 16px;
  border: 1px solid rgba(29, 47, 76, 0.18);
  background: #1d2f4c;
  color: #ffffff;
}

.sffc-cv-match-studio__recommended-searchbar-submit:hover,
.sffc-cv-match-studio__recommended-searchbar-submit:focus-visible {
  transform: translateY(-1px);
  box-shadow: 0 12px 24px rgba(15, 23, 42, 0.08);
}

.sffc-cv-match-studio__recommended-searchbar-submit:disabled {
  opacity: 0.72;
  cursor: wait;
  transform: none;
}

.sffc-cv-match-studio__mobile-search-toggle,
.sffc-cv-match-studio__mobile-search-close {
  display: none;
}

.sffc-cv-match-studio__mobile-search-close {
  appearance: none;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  padding: 0;
  border: 1px solid rgba(29, 47, 76, 0.1);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.96);
  color: #1d2f4c;
  cursor: pointer;
}

.sffc-cv-match-studio__mobile-search-close svg {
  width: 14px;
  height: 14px;
}

.sffc-cv-match-studio__main-utility-actions {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}

.sffc-cv-match-studio__topbar,
.sffc-cv-match-studio__topbar--profile,
.sffc-cv-match-studio__topbar--review,
.sffc-cv-match-studio__topbar--outreach,
.sffc-cv-match-studio__topbar--help,
.sffc-cv-match-studio__topbar--discovery,
.sffc-cv-match-studio__job-topbar {
  padding: 0 0 14px;
  margin-bottom: 18px;
  border-bottom: 1px solid rgba(46, 62, 92, 0.14);
  background: transparent;
  border-radius: 0;
  box-shadow: none;
}

.sffc-cv-match-studio__topbar-copy h2,
.sffc-cv-match-studio__results-title {
  font-family: Tahoma, Arial, sans-serif;
  font-weight: 400;
  color: #1d2f4c;
}

.sffc-cv-match-studio__topbar-copy h2 {
  font-size: 34px;
  line-height: 1.08;
  letter-spacing: -0.03em;
}

.sffc-cv-match-studio__results-title {
  font-size: 32px;
  line-height: 1.08;
}

.sffc-cv-match-studio__results-count {
  color: #738093;
  font-size: 13px;
  font-weight: 400;
}

/* Buttons */
.sffc-cv-match-studio__submit,
.sffc-cv-match-studio__topbar-button,
.sffc-cv-match-studio__open-button,
.sffc-cv-match-studio__results-cta-button,
.sffc-cv-match-studio__interview-submit {
  border-radius: 10px;
  box-shadow: none;
  font-family: Tahoma, Arial, sans-serif;
  font-weight: 400;
  letter-spacing: 0;
}

.sffc-cv-match-studio__submit,
.sffc-cv-match-studio__topbar-button.is-primary,
.sffc-cv-match-studio__results-cta-button,
.sffc-cv-match-studio__interview-submit {
  background: #1d2f4c;
  color: #fff;
  border: 1px solid rgba(29, 47, 76, 0.18);
}

.sffc-cv-match-studio__topbar-button.is-secondary,
.sffc-cv-match-studio__open-button {
  background: rgba(255, 255, 255, 0.66);
