/* Landing */
.sffc-cv-match-studio__hero {
  max-width: 760px;
  margin: 96px auto 20px;
  text-align: left;
}

.sffc-cv-match-studio__hero h1 {
  font-family: Tahoma, Arial, sans-serif;
  font-weight: 400;
  font-size: clamp(42px, 5.2vw, 68px);
  line-height: 1.02;
  color: #1d2f4c !important;
}

.sffc-cv-match-studio__hero h2 {
  font-family: Tahoma, Arial, sans-serif;
  font-size: clamp(26px, 3vw, 42px);
  line-height: 1.08;
  font-weight: 400;
  color: #6d6a63;
  margin: 4px 0 14px;
}

.sffc-cv-match-studio__hero p {
  max-width: 760px;
  font-size: 17px;
  line-height: 1.82;
  color: #687384;
}

.sffc-cv-match-studio__prompt-search {
  max-width: 840px;
  margin: 0 auto 18px;
}

.sffc-cv-match-studio__prompt-search-shell {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  min-height: 68px;
  padding: 8px 10px 8px 12px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.92);
  box-shadow: 0 14px 30px rgba(17, 30, 46, 0.05);
  backdrop-filter: blur(14px);
}

.sffc-cv-match-studio__prompt-search.is-dragover
  .sffc-cv-match-studio__prompt-search-shell,
[data-cv-match-dropzone].is-dragover
  .sffc-cv-match-studio__prompt-search-shell {
  border-color: rgba(29, 47, 76, 0.18);
  box-shadow: 0 18px 34px rgba(17, 30, 46, 0.08),
    0 0 0 3px rgba(29, 47, 76, 0.05);
}

.sffc-cv-match-studio__prompt-input {
  width: 100%;
  display: block;
  min-height: 60px !important;
  max-height: 32px;
  padding: 12px !important;
  border: 0;
  border-radius: 6px !important;
  background: white !important;
  box-shadow: none;
  resize: vertical !important;
  outline: none;
  overflow-y: auto;
  color: #1d2f4c;
  font-size: 20px !important;
  line-height: 1.45;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important;
  text-align: center;
  transition: all 0.2s !important;
}

.sffc-cv-match-studio__prompt-input::placeholder {
  color: #9aa4b2;
}

.sffc-cv-match-studio__prompt-input:focus {
  color: #13283f;
}

.sffc-cv-match-studio__prompt-input::-webkit-scrollbar {
  width: 8px;
}

.sffc-cv-match-studio__prompt-input::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(29, 47, 76, 0.16);
}

.sffc-cv-match-studio__prompt-search-upload {
  appearance: none;
  width: 44px;
  height: 44px;
  border: 0;
  border-radius: 999px;
  background: rgba(29, 47, 76, 0.06);
  color: #5d6e84;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.18s ease, transform 0.18s ease, color 0.18s ease;
}

.sffc-cv-match-studio__prompt-search-upload:hover,
.sffc-cv-match-studio__prompt-search-upload:focus-visible {
  background: rgba(29, 47, 76, 0.1);
  color: #1d2f4c;
  transform: translateY(-1px);
}

.sffc-cv-match-studio__prompt-search-upload svg {
  width: 18px;
  height: 18px;
}

.sffc-cv-match-studio__prompt-search-actions {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.sffc-cv-match-studio__tool-hint {
  color: #6d7686;
  font-size: 12px;
}

.sffc-cv-match-studio__submit {
  min-height: 44px;
  padding: 0 18px;
  border-radius: 999px;
  border: 1px solid rgba(29, 47, 76, 0.18);
  background: #1d2f4c;
  color: #ffffff;
  font-family: Tahoma, Arial, sans-serif;
  font-size: 13px;
  font-weight: 400;
}

.sffc-cv-match-studio__prompt-search-meta {
  margin-top: 8px;
  padding: 0 12px;
}

.sffc-cv-match-studio__prompt-search-source
  .sffc-cv-match-studio__cv-source-select {
  min-width: 168px;
  max-width: 210px;
  height: 40px;
  border-radius: 999px;
  background: rgba(29, 47, 76, 0.05);
}

.sffc-cv-match-studio__cv-source-select-wrap::after {
  border-right-color: rgba(29, 47, 76, 0.7);
  border-bottom-color: rgba(29, 47, 76, 0.7);
}

.sffc-cv-match-studio__cv-source-select {
  background: rgba(255, 255, 255, 0.7);
  color: #1d2f4c;
  border: 1px solid rgba(44, 61, 92, 0.08);
}

.sffc-cv-match-studio__tiles {
  max-width: 960px;
  gap: 14px;
}

.sffc-cv-match-studio__tiles-status {
  font-size: 14px;
  line-height: 1.75;
  color: #687384;
}

.sffc-cv-match-studio__benefit-card {
  display: grid;
  gap: 0;
  min-width: 0;
  border-radius: 24px;
  overflow: hidden;
  border: 1px solid rgba(13, 53, 62, 0.12);
  background: #0d353e;
  box-shadow: 0 22px 42px rgba(12, 25, 38, 0.16);
}

.sffc-cv-match-studio__benefit-card-media {
  position: relative;
  aspect-ratio: 16 / 10;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.08);
}

.sffc-cv-match-studio__benefit-card-media::after {
  content: "";
  position: absolute;
  inset: auto 0 0;
  height: 58%;
  background: linear-gradient(
    180deg,
    rgba(13, 53, 62, 0) 0%,
    rgba(13, 53, 62, 0.84) 100%
  );
}

.sffc-cv-match-studio__benefit-card-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.sffc-cv-match-studio__benefit-card-copy {
  display: grid;
  gap: 8px;
  padding: 16px 16px 18px;
}

.sffc-cv-match-studio__benefit-card-eyebrow {
  display: inline-flex;
  width: fit-content;
  min-height: 28px;
  align-items: center;
  padding: 0 10px;
  border-radius: 999px;
  background: rgba(204, 255, 27, 0.16);
