  line-height: 1.2;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.sffc-cv-match-studio__benefit-card-copy strong {
  display: block;
  color: #ffffff;
  font-family: Tahoma, Arial, sans-serif;
  font-size: 24px;
  line-height: 1.08;
  font-weight: 400;
  letter-spacing: -0.03em;
}

.sffc-cv-match-studio__benefit-card-copy p {
  margin: 0;
