}

.sffc-cv-match-studio__tile-role-copy strong {
  font-size: 18px;
  font-family: Tahoma, Arial, sans-serif;
  font-weight: 400;
  color: #ffffff;
}

.sffc-cv-match-studio__tile-role-copy p,
.sffc-cv-match-studio__tile-role-signal span {
  font-size: 12px;
  line-height: 1.45;
  color: #ffffff;
}

/* Scanning */
.sffc-cv-match-studio__scanner {
  max-width: 1080px;
  margin-top: 48px;
  padding: 10px 0 0;
  background: transparent;
  border: 0;
}

.sffc-cv-match-studio__scanner-head h2 {
  font-family: Tahoma, Arial, sans-serif;
  font-weight: 400;
  color: #1d2f4c;
}

.sffc-cv-match-studio__scanner-head p {
  max-width: 760px;
  font-size: 16px;
  line-height: 1.8;
}

.sffc-cv-match-studio__progress-track {
  background: rgba(46, 62, 92, 0.1);
}

.sffc-cv-match-studio__progress-fill {
  background: #294570;
}

.sffc-cv-match-studio__scan-step {
  padding: 18px 18px 16px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.18);
  border: 1px solid rgba(44, 61, 92, 0.08);
