  padding: 0;
  gap: 18px;
  background: transparent;
}

.sffc-cv-match-studio__results-head {
  align-items: end;
  margin-bottom: 0;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(46, 62, 92, 0.14);
}

.sffc-cv-match-studio__results-stats {
  gap: 10px;
}

.sffc-cv-match-studio__stat-card {
  padding: 12px 14px 11px;
  border-radius: 22px;
